import type { MetadataRoute } from "next";

// PWA manifest — Next App Router otomatik olarak <link rel="manifest"> ekler.
// İkonlar scripts/build-favicons.mjs ile üretilir.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "TravelShop Booking",
    short_name: "TravelShop",
    description:
      "Discover unique guided tours and cultural experiences across Turkey and the world with TravelShop Booking.",
    start_url: "/",
    display: "standalone",
    background_color: "#854ec9",
    theme_color: "#854ec9",
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
